def generate_x_fb_session_id():
    nid_raw = secrets.token_bytes(8)
    nid = base64.urlsafe_b64encode(nid_raw).decode('utf-8').rstrip('=')

    tid = str(random.randint(10, 99))
    nc = str(random.randint(0, 2))
    fc = str(random.randint(0, 1))
    bc = str(random.randint(0, 1))

    cid_input = secrets.token_hex(16)
    cid = hashlib.md5(cid_input.encode()).hexdigest()

    session_id = f"nid={nid};tid={tid};nc={nc};fc={fc};bc={bc};cid={cid}"
    return session_id, cid  # Return both

